-- Step 2 of 3 (see 0005 and 0007). Orders from the 2019 import point at customers that were
-- hard-deleted back then. Re-point them at the placeholder from 0004. This runs after 0005, so the
-- foreign key already rejects any new orphan while this runs. Safe to rerun: it matches nothing once
-- done. Row locks are taken only on the orphaned rows, and the placeholder must exist.
SET LOCAL lock_timeout = '5s';

DO $$
DECLARE
  placeholder_id bigint;
BEGIN
  SELECT id INTO placeholder_id
  FROM customers
  WHERE email = 'deleted-customer@internal.invalid';

  IF placeholder_id IS NULL THEN
    RAISE EXCEPTION 'placeholder customer deleted-customer@internal.invalid is missing (see 0004)';
  END IF;

  UPDATE orders AS o
  SET customer_id = placeholder_id
  WHERE NOT EXISTS (SELECT 1 FROM customers AS c WHERE c.id = o.customer_id);
END
$$;

